competencyQuestions.sparql:
SELECT ?codigo ?descricao WHERE {
  ?h a cc:BNCCYear3Skill , cc:BNCCNumbersSkill ;
     cc:hasCurriculumCode ?codigo ;
     cc:hasOfficialDescription ?descricao .
} ORDER BY ?codigo

SELECT ?ano ?unidade (COUNT(DISTINCT ?h) AS ?habilidades) WHERE {
  ?h a cc:BNCCSkill ; cc:belongsToGrade ?g ; cc:belongsToCurriculumDomain ?d .
  ?g rdfs:label ?ano . FILTER(langMatches(lang(?ano), "pt-BR"))
  ?d rdfs:label ?unidade . FILTER(langMatches(lang(?unidade), "pt-BR"))
} GROUP BY ?ano ?unidade ORDER BY ?ano ?unidade

SELECT ?conceito ?estadoMapeamento WHERE {
  ?h cc:hasCurriculumCode "EF03MA07" ;
     cc:addressesMathematicalConcept ?c ;
     cc:conceptMappingStatus ?estadoMapeamento .
  ?c rdfs:label ?conceito . FILTER(langMatches(lang(?conceito), "pt-BR"))
} ORDER BY ?conceito

SELECT ?preRequisito ?direto WHERE {
  ?c cc:isPrerequisiteOf cc:PercentageConcept .
  ?c rdfs:label ?preRequisito . FILTER(langMatches(lang(?preRequisito), "pt-BR"))
  BIND(EXISTS { ?r cc:prerequisiteConcept ?c ; cc:dependentConcept cc:PercentageConcept } AS ?direto)
} ORDER BY DESC(?direto) ?preRequisito

SELECT ?codigo (GROUP_CONCAT(DISTINCT ?conceito; separator=", ") AS ?conceitosDependentes) WHERE {
  cc:MultiplicationConcept cc:isPrerequisiteOf ?c .
  ?h cc:addressesMathematicalConcept ?c ; cc:hasCurriculumCode ?codigo .
  { ?h a cc:BNCCYear4Skill } UNION { ?h a cc:BNCCYear5Skill }
  ?c rdfs:label ?conceito . FILTER(langMatches(lang(?conceito), "pt-BR"))
} GROUP BY ?codigo ORDER BY ?codigo

SELECT ?ano (COUNT(?h) AS ?semAtividade) WHERE {
  ?h a cc:BNCCSkill ; cc:currentActivityCoverageStatus "NOT_COVERED" ; cc:belongsToGrade ?g .
  ?g rdfs:label ?ano . FILTER(langMatches(lang(?ano), "pt-BR"))
} GROUP BY ?ano ORDER BY ?ano

SELECT ?conceitoLocal ?relacao ?iriOntoMathEdu WHERE {
  ?c cc:sourceOntology <http://ontomathpro.org/ontomathedu#> ;
     cc:alignmentRelation ?relacao .
  OPTIONAL { ?c cc:sourceIRI ?iriOntoMathEdu }
  ?c rdfs:label ?conceitoLocal . FILTER(langMatches(lang(?conceitoLocal), "pt-BR"))
} ORDER BY ?relacao ?conceitoLocal

SELECT ?anterior ?dependente ?fundamentacao WHERE {
  ?r a cc:PrerequisiteRelation ;
     cc:prerequisiteConcept ?a ; cc:dependentConcept ?d ;
     rdfs:comment ?fundamentacao .
  FILTER(langMatches(lang(?fundamentacao), "pt-BR"))
  ?a rdfs:label ?anterior . FILTER(langMatches(lang(?anterior), "pt-BR"))
  ?d rdfs:label ?dependente . FILTER(langMatches(lang(?dependente), "pt-BR"))
} ORDER BY ?anterior ?dependente

SELECT ?familia (GROUP_CONCAT(DISTINCT ?codigo; separator=", ") AS ?habilidades) (GROUP_CONCAT(DISTINCT ?rep; separator=", ") AS ?representacoes) WHERE {
  ?f a cc:ActivityFamilyProfile ; cc:addressesBNCCSkill ?h .
  ?h a cc:BNCCYear1Skill ; cc:hasCurriculumCode ?codigo .
  OPTIONAL { ?f cc:hasRepresentation ?r . ?r rdfs:label ?rep . FILTER(langMatches(lang(?rep), "pt-BR")) }
  ?f rdfs:label ?familia . FILTER(langMatches(lang(?familia), "pt-BR"))
} GROUP BY ?familia ORDER BY ?familia

SELECT ?familia ?usaPictogramas WHERE {
  ?f a cc:ActivityFamilyProfile ;
     cc:requiresDragging false ;
     cc:hasActivityAffordance cc:KeyboardAlternativeAffordance .
  OPTIONAL { ?f cc:usesPictograms ?usaPictogramas }
  ?f rdfs:label ?familia . FILTER(langMatches(lang(?familia), "pt-BR"))
} ORDER BY ?familia
